            "got 8000gold and 4 waking deep shard": "拿到了8000金币和4个觉醒深渊碎片",
            "how is combat level calculated?": "战斗等级是怎么计算的？",
            "i need a search bar in guild bank, there are so many items...": "公会仓库需要一个搜索栏，东西太多了……",
