            "is there any ways to buff the speed of mining?": "有没有什么方法可以提升采矿速度？",
            "nice thanks, no wonder my combat level seems stuck I've only been leveling magic": "好的谢谢，难怪我的战斗等级不动了，我只升级了魔法",
            "not at the moment": "目前没有",
